func typeInto(t *testing.T, m Model, s string) Model {
	t.Helper()
	return feed(t, m, testutil.Type(s)...)
}

// resultsModel returns a browser on its results screen, having actually
// submitted a search. searchedModel feeds tags in without submitting, which is
// enough to test where results land but leaves the browser on the form — the
// results table is only rebuilt while the tags screen is showing.
func resultsModel(t *testing.T, msgs ...tea.Msg) Model {
	t.Helper()

	m := typeInto(t, browsingModel(t), "api")
	m = feed(t, m, testutil.Key("enter"))
	if m.registryBrowser.state != browserStateTags {
		t.Fatalf("the search did not reach the results screen (state %d)", m.registryBrowser.state)
	}
	if len(msgs) == 0 {
		msgs = []tea.Msg{
			MultiRegistryTagsLoadedMsg{EntryKey: "prod", RegistryURL: "registry.example.com", Alias: "prod", Repo: "api", Tags: []string{"v1", "v2"}},
			MultiRegistryTagsLoadedMsg{EntryKey: "hub", RegistryURL: "docker.io", Alias: "hub", Repo: "api", Tags: []string{"latest"}},
		}
	}
	return feed(t, m, stampGen(m, msgs...)...)
}

// stampGen gives the tag messages the generation the open browser accepts: the
// fixtures are written before the search whose answers they stand for, so they
// cannot know it (DEVDESK-393). Messages sent with no search keep Gen 0, which
// is what a fresh browser holds.
func stampGen(m Model, msgs ...tea.Msg) []tea.Msg {
	gen := m.RegistryBrowserGen()
	out := make([]tea.Msg, len(msgs))
	for i, msg := range msgs {
		switch v := msg.(type) {
		case MultiRegistryTagsLoadedMsg:
			v.Gen = gen
			msg = v
		case MultiRegistryTagsMetaMsg:
			v.Gen = gen
			msg = v
		}
		out[i] = msg
	}
	return out
}
