// c.3: the search action is the IS-01 search, not the tags.
func TestSearchActionOnAShortNameSearches(t *testing.T) {
	fake := &fakeSearcher{}
	withImageSearcher(t, fake)
	rec := withFullTagRecorder(t)

	m := typeInto(t, browsingModel(t), "nginx")
